import { defineConfig } from 'electron-vite';
import react from '@vitejs/plugin-react';


export default defineConfig({
  main: {
    build: {
      // https://electron-vite.org/guide/dev#dependencies-vs-devdependencies
      // For the main process and preload, the best practice is to externalize dependencies and only bundle our own code.
      target: 'node24.15',
      sourcemap: true,
    },
  },
  preload: {
    build: {
      target: 'node24.15',
      sourcemap: true,
      rollupOptions: {
        output: {
          format: 'cjs',
        },
      },
    },
  },
  renderer: {
    plugins: [react()],
    build: {
      target: 'chrome148',
      sourcemap: true,
      chunkSizeWarningLimit: 3e6,
    },
    server: {
      port: 3001,
      host: '127.0.0.1',
    },
  },
});

// eslint-disable-next-line import/no-extraneous-dependencies
import type { defineConfig } from 'i18next-cli';

const configBase: Omit<Parameters<typeof defineConfig>[0], 'locales'> = {
  extract: {
    input: [
      'src/renderer/**/*.{ts,tsx}',
      'src/main/**/*.ts',
      'src/common/**/*.ts',
      'src/preload/**/*.ts',
    ],
    output: 'locales/{{language}}/{{namespace}}.json',
    defaultNS: 'translation',
    functions: [
      't',
      '*.t',
    ],
    transComponents: [
      'Trans',
    ],
    ignoredAttributes: ['data-testid', 'aria-label', 'role'],

    // Keep in sync between i18next.config.base.ts and i18nCommon.js:
    keySeparator: false,
    nsSeparator: false,
  },
  types: {
    input: [
      'locales/{{language}}/{{namespace}}.json',
    ],
    output: 'src/types/i18next.d.ts',
  },
};

export default configBase;

// eslint-disable-next-line import/no-extraneous-dependencies
import { defineConfig } from 'i18next-cli';

import configBase from './i18next.config.base.js';


export default defineConfig({
  ...configBase,
  locales: ['en'],
});
